"""LSUN bedroom: our method and PnP-CM on every task, with the bedroom consistency model (run from PnP-CM/).
Ours: each task's configuration EXACTLY as on CelebA-HQ (no retuning); only the combination weights are refitted, on 128 images generated by the
bedroom model.  PnP-CM: its exact linear step / its gradient solver, CelebA-HQ settings (the repository ships none for bedroom).  58 test images."""
import subprocess, os, glob, re, time, itertools, numpy as np, torch, lpips
from PIL import Image
L = "../mode_probe"; P = "../pnpcm_env/bin/python"; os.environ["DSET"] = "bedroom"
CT = "SIGS=0.9000,0.4500,0.3300,0.1650 SIGPOS=0,1,2,3"
OURS = {"sr_bicubic": "sr_bicubic LINEXACT=1", "deblur_gauss": "deblur_gauss LINEXACT=1", "inpainting": "inpainting LINEXACT=1 FW=1 FWP=0.5",
        "jpeg": "jpeg JPROJ=1 JSOFT=1 JCOLD=1 FW=1 FWP=0.5 FWSTEPS=1,2,3", "deblur_nl": "deblur_nl WARMX=lin NLKER=1 MEC=step FW=1 FWP=0.5 FWMIN=0.4",
        "hdr": "deblur_nl NEWOP=hdr HDRX=1 SIGS=3.0,0.635,0.56,0.459 SIGPOS=0,1,2,3", "quant": "deblur_nl NEWOP=quant FW=1 FWP=0.5 FWMIN=0.4",
        "onebit": "deblur_nl NEWOP=onebit OBMEAN=1.0,0.5,0.3,0.2 FW=1 FWP=0.5 FWMIN=0.4", "prmask": "phase_retrieval INIT=hio HIO_K=4 HIO_N=1000 PRLIN=1 PRSIGN=none LINEXACT=1 FW=1 FWP=0.5",
        "ct30": "deblur_nl NEWOP=ct CT_K=30 CT_SVD=1 RHOX=3 SIGS=0.5,0.25,0.1,0.02", "ct60": "deblur_nl NEWOP=ct CT_K=60 CT_SVD=1 RHOX=3 SIGS=0.5,0.25,0.1,0.02",
        "ctnl30": f"deblur_nl NEWOP=ctnl CT_K=30 RHOX=0.1 CTNL_N=4 {CT} SIGTOLD=1.0", "ctnl60": f"deblur_nl NEWOP=ctnl CT_K=60 RHOX=0.1 CTNL_N=4 {CT} SIGTOLD=1.2",
        "gamma": "deblur_nl NEWOP=gamma", "blurq": "deblur_nl NEWOP=blurq", "blurclip": "deblur_nl NEWOP=blurclip SPLIT_EV=0.3"}
PNP = {"sr_bicubic": "sr_bicubic LINEXACT=1", "deblur_gauss": "deblur_gauss LINEXACT=1", "inpainting": "inpainting LINEXACT=1", "jpeg": "jpeg SOLVER=repo", "deblur_nl": "deblur_nl SOLVER=repo",
       "hdr": "deblur_nl NEWOP=hdr SOLVER=repo", "quant": "deblur_nl NEWOP=quant SOLVER=repo", "onebit": "deblur_nl NEWOP=onebit SOLVER=repo", "prmask": "phase_retrieval SOLVER=repo",
       "ctnl30": "deblur_nl NEWOP=ctnl CT_K=30 SOLVER=repo RHOX=1 REPO_LR=3e-2", "ctnl60": "deblur_nl NEWOP=ctnl CT_K=60 SOLVER=repo RHOX=1 REPO_LR=3e-2",
       "gamma": "deblur_nl NEWOP=gamma SOLVER=repo", "blurq": "deblur_nl NEWOP=blurq SOLVER=repo", "blurclip": "deblur_nl NEWOP=blurclip SOLVER=repo"}
MAXP = int(os.environ.get("MAXP", "20")); run = []; g = [0]
def slot():
    while len([p for p in run if p.poll() is None]) >= MAXP: time.sleep(3)
def launch_pnp(t, sh):
    c = PNP[t].split(); env = dict(os.environ, CUDA_VISIBLE_DEVICES=str(g[0] % 8), DATA=os.path.realpath(f"{L}/data_bed"), SHARD=sh, SAMPLE_SEED="1", RESTART="never", NOISE="white", NOLOG="1", MODE="unified", TILT="0", OMP_NUM_THREADS="4")
    env.update(dict(kv.split("=", 1) for kv in c[1:])); g[0] += 1
    return subprocess.Popen([P, f"{L}/unified.py", f"fin_bedpnp_{t}", f"--deg={c[0]}"], env=env, stdout=open(f"{L}/logs_x/bedpnp_{t}_{sh.split(':')[0]}.out", "w"), stderr=subprocess.STDOUT)
for t in PNP:
    for sh in ("0:29", "29:58"): slot(); run.append(launch_pnp(t, sh))
for i, (t, c) in enumerate(OURS.items()):
    slot(); slot()
    env = dict(os.environ, TAG=f"bed{t}", KEY=t, CFGSTR=c, NSTEP="4", MODES="scalar zband8", CALSH="0:64 64:128", TESTSH="0:29 29:58", CALDATA=f"{L}/data_bedgen", TESTDATA=f"{L}/data_bed", NGPU="8", PAR="4", GOFF=str(2 * i))
    run.append(subprocess.Popen(["bash", f"{L}/launch_llewd.sh"], env=env, stdout=open(f"{L}/logs_x/launch_bed{t}.log", "w"), stderr=subprocess.STDOUT, cwd=L)); run.append(run[-1])
[p.wait() for p in run]
lp = lpips.LPIPS(net="vgg", verbose=False).cuda(); F = torch.tensor(list(itertools.product([1.0, -1.0], repeat=3))).view(8, 3, 1, 1)
def score(pat, flip=False):
    Ps = []; Ls = []
    for rf in glob.glob(f"{L}/exp_fin_{pat}_s*/raw_*.pt"):
        d = os.path.dirname(rf); i = int(re.findall(r"raw_(\d+)\.pt", rf)[0]); lab = glob.glob(f"{d}/image_samples/*/labels/orig_{i}.png")
        gt = torch.from_numpy(np.asarray(Image.open(lab[0]).convert("RGB")).astype(np.float32) / 255).permute(2, 0, 1) * 2 - 1; x = torch.load(rf)["x_raw"][0].float().clamp(-1, 1)
        if flip: c = F * x; x = c[int(((c - gt) ** 2).mean(dim=(1, 2, 3)).argmin())]
        with torch.no_grad(): Ps.append(float(10 * torch.log10(1 / (((x - gt) / 2) ** 2).mean()))); Ls.append(float(lp(x[None].cuda(), gt[None].cuda())))
    return f"{np.mean(Ps):.2f}/{np.mean(Ls):.3f}" + ("" if len(Ps) == 58 else f" (n={len(Ps)})") if Ps else "missing"
print("| Task | PnP-CM | Ours, scalar extrapolation | Ours, 8 bands + data-fit term |\n|---|---|---|---|")
for t in OURS:
    f = t == "prmask"; print(f"| {t} | {score(f'bedpnp_{t}', f) if t in PNP else 'n/a'} | {score(f'bed{t}test_scalar_{t}_*', f)} | {score(f'bed{t}test_zband8_{t}_*', f)} |", flush=True)
